var n=`0506-shakshuka`;var t=`world-0506`;var a=`IL`;var o=`western-asia`;var r=4;var s=38;var g={en:`Shakshuka`,ua:`Шакшука`};var l={en:`A traditional dish from Israel, centered on yellow onion, red bell pepper, garlic, tomato. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Ізраїль. Основні складники: жовта цибуля, червоний солодкий перець, часник, помідор. Домашній варіант із кількостями продуктів за етапами приготування.`};var d=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`yellow-onion`,180,`g`],[`red-bell-pepper`,200,`g`],[`extra-virgin-olive-oil`,60,`ml`],[`garlic`,4,`clove`],[`ground-cumin`,4,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 17 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 17 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:17,i:[[`tomato`,750,`g`],[`tomato-paste`,40,`g`],[`hot-paprika`,4,`g`]]},{en:`Poach the listed ingredients in barely simmering liquid for about 9 minutes until tender and cooked through.`,ua:`Пошируйте зазначені продукти в рідині без бурхливого кипіння приблизно 9 хвилин до готовності й м’якості.`,t:[`poaching`],m:9,i:[[`chicken-egg`,5,`pcs`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parsley`,24,`g`]]}];var u={slug:n,id:t,country:`IL`,region:o,servings:4,minutes:38,title:g,text:l,steps:d};export{a as country,u as default,t as id,s as minutes,o as region,r as servings,n as slug,d as steps,l as text,g as title};